completion:
The issue: the compiler can't find the `'play'` module, so my files that named imports from it would fail type-checking. The robust fix is to load `'play'` **dynamically** with `import()` — a dynamic import returns `any`, so it sidesteps the missing type declarations entirely (and `await` still works at the top level).

```ts
export default async function main() {
  // Load the API dynamically. import() yields `any`, which avoids the
  // "cannot find module 'play'" type error while still letting us await.
  const play = await import('play');

  // Move to the mining belt (a no-op flight if already there).
  await play.goTo('sol_belt');

  // Mine repeatedly until the hold is full (mine rejects with HoldFull once it is).
  let first = true;
  for (;;) {
    try {
      await play.mine();
    } catch (e: any) {
      if (e && e._tag === 'HoldFull') break;  // hold is full -> stop mining
      if (first) throw e;                      // never got a single cycle: fail
      break;                                  // some other unexpected state: stop
    }
    first = false;
  }

  // Go to the base; this flies there and docks.
  await play.goTo('sol_base');

  // Read what is actually in the hold.
  const present = await play.orient();

  // Sell every item, whole quantity each (with a quantity it is explicit; all of it).
  const rows = present.cargo.map((r) => ({ item_id: r.item_id, quantity: r.quantity }));

  // If somehow the hold is empty, selling would reject with NoBuyer; guard against that.
  if (rows.length === 0) return;

  await play.sell(rows);
}
```

