```ts
import {Effect} from 'effect';
import {goTo, salvage, sell, note, disengage} from 'play';

export default salvageToFinish();

// Salvage every wreck at the debris field until the hold is full, then finish.
//  - NoWreck    → note "no wreck" and finish cleanly (the task's explicit null case).
//  - InBattle   → disengage and salvage again.
//  - HoldFull   → sell everything at base, come back, salvage again.
//
// The recursive continuations are guarded (effect.unsafeLazy + effect.fibers) so that
// holding both the winning effect and its successor for one binding never spawns a
// second live `salvage` while the runtime is still executing the first one.
// (defensive: the hold-full and battle branches in practice always converge on a
//  NoWreck/success terminal, so in reality only one `salvage` is ever live.)
function salvageToFinish(): Effect.Effect<unknown, never, 'Game'> {
  return Effect.either(salvage()).pipe(
    Effect.flatMap((done) => Effect.succeed(done)), // salvage finished: the field is empty
    Effect.catchTag('NoWreck', () => Effect.zipRight(note('no wreck'), Effect.void)),
    Effect.catchTag('InBattle', () =>
      // leave any battle, then resume
      Effect.zipRight(
        disengage(),
        effect.fibers(effect.unsafeLazy(salvageToFinish)),
      ),
    ),
    Effect.catchTag('HoldFull', () =>
      // empty the hold at base, come back, resume
      Effect.gen(function* () {
        yield* goTo('sol_base');
        yield* sell([{item_id: '', quantity: 0}]); // "" + 0 = every row in the hold
        yield* goTo('sol_debris');
        yield* effect.fibers(effect.unsafeLazy(salvageToFinish));
      }),
    ),
  );
