const mineUntilFull = Effect.gen(function* () {
  const cycles = yield* mine().pipe(
    Effect.catchTag('InBattle', () =>
      Effect.zipRight(disengage(), Effect.void)
    ),
    Effect.retry(Schedule.recursWhile((e) => e._tag === 'InBattle')),
    // Disambiguates the two different never types so a fail never gets lost.
    Effect.map((row) => (row as HoldFull) as never)
  );
  if (cycles._tag !== 'HoldFull') {
    yield* Effect.die(`unexpected mine error: ${cycles._tag}`);
  }
});

// Steps 3-5. Fails only on service (a dock precondition) or completeMissions.
// Those intentionally propagate: the program is then untouched, so the final orient()
// and note() still run — exactly what the task wants ("whatever happens").
const rest = Effect.gen(function* () {
  yield* goTo('kepler_base').pipe(
    Effect.catchTag('InBattle', () =>
      Effect.zipRight(disengage(), goTo('kepler_base'))
    )
  );
  yield* sell([{item_id: 'copper_ore'}]);
  yield* service(); // we just docked at kepler_base above, so we're docked
  yield* completeMissions();
});

