  yield* mineUntilFull;

  const restOutcome = yield* rest.pipe(Effect.either);
  if (restOutcome._tag === 'Right') {
    yield* Effect.logInfo(`rest step failed: ${restOutcome.right._tag}`);
  }

  // The last thing the program does, regardless of the above.
  const present = yield* orient();
  return yield* note(`final credits: ${present.credits}`);
});
