import {Effect} from 'effect';
import {goTo, mine, sell, service, note, orient} from 'play';

export default Effect.gen(function* () {
  const state = yield* orient();
  if (state.poi !== 'sol_belt') {
    yield* note(`warning: expected sol_belt, actually at ${state.poi}`);
  }

  // Mine repeatedly until the hold is full (mine fails with HoldFull)
