            yield* note(`hold full (${e.used}/${e.capacity}); stop mining`);
            return Effect.assign({mined: false});
          }
          // unexpected error (InBattle / NotAtBelt) — fail with it
          return Effect.fail(e);
        },
        onSuccess: (r) => {
          const total = r.reduce((s: number, row) => s + row.quantity, 0);
          yield* note(`mined ${total} units`);
          return Effect.succeed({});
        },
      }),
    );
  }

  // Fly to the base and dock
  const arrived = yield* goTo('sol_base');
  yield* note(`arrived at ${arrived.poi} (docked ${arrived.docked_at ?? '—'}), fuel used ${arrived.fuel_used}`);

  // Sell everything in the hold, every item (omit quantity => all of it)
  const hold = yield* orient();
  const want = hold.cargo.map((r) => ({item_id: r.item_id}));
  if (want.length === 0) {
    yield* note('nothing in the hold to sell');
  } else {
    const sold = yield* sell(want);
    const kinds = sold.fills.length;
    yield* note(`sold for ${sold.total} (kinds: ${kinds}, unsold: ${sold.short.length})`);
  }

  // Full tank, full hull
  const svc = yield* service();
  yield* note(`serviced: fuel ${svc.fuel}, hull ${svc.hull}, cost ${svc.cost}`);
