```ts
import {Effect} from 'effect';
import {
  goTo,
  mine,
  sell,
  service,
  completeMissions,
  orient,
  note,
  disengage,
  type Row,
} from 'play';

// A Row is {item_id: string; quantity: number}. No error in the 'mine' error union
// (InBattle | NotAtBelt | HoldFull) is shaped like a Row, so this tells us a cycle
// actually returned cargo (the hold had room) versus throwing.
const isRow = (x: unknown): x is Row =>
  typeof x === 'object' &&
  x !== null &&
  typeof (x as Row).item_id === 'string' &&
  typeof (x as Row).quantity === 'number';

// Mine repeatedly at the belt we are at. A cycle that fills the hold throws HoldFull,
// which we swallow to end the run. InBattle is handled by disengaging then re-mining.
// Bounded so a pathologically-never-full hold cannot loop forever.
function mineHold(): Effect.Effect<Row[], never, 'Game'> {
  const MAX = 200;
  let rows: Row[] = [];

  const cycle = Effect.gen(function* () {
    // Disengage first so a lingering battle can't keep re-failing the mine.
    yield* disengage();
    return yield* mine().pipe(
      Effect.mapError((e) =>
        e._tag === 'InBattle'
          ? {tag: 'inBattle' as const}
          : e._tag === 'HoldFull'
            ? {tag: 'full' as const}
            : e._tag === 'NotAtBelt'
              ? {tag: 'notAtBelt' as const}
              : e,
      ),
    );
  });

  for (let i = 0; i < MAX; i++) {
    const out = yield* cycle().pipe(
      Effect.mapError((e) =>
        'tag' in e && e.tag === 'full' ? {tag: 'full' as const} : e,
      ),
    );
    if (isRow(out)) {
      rows = [...rows, out];
    }
  }
  return rows;
}

export default Effect.gen(function* () {
  // 1) fly to the belt
  yield* goTo('kepler_belt');

  // 2) mine until the hold is full, disengaging from any pirate
  yield* mineHold();

  // 3) fly to kepler_base and dock
  yield* goTo('kepler_base');

  // 4) sell the copper_ore we hauled
  yield* sell([{item_id: 'copper_ore'}]);

  // 5) service the ship
  yield* service();

  // 6) turn in missions; ignore "there is nothing to complete here"
  yield* completeMissions().pipe(
    Effect.catchTag('NothingCompletable', () => Effect.void),
  );
})().pipe(
  // whatever happened above, the last thing the program does is note current credits
  Effect.ensuring(
    orient().pipe(Effect.flatMap((p) => note(`credits: ${p.credits}`))),
  ),
);
```

A couple of notes on the choices:

- **`Effect.ensuring`** runs the credits-`note` after the `Effect.gen` body no matter how it ends (success or failure), and `orient` never fails, so that note is guaranteed to be the last thing executed.
- **`mine` stops on `HoldFull`**: I fold it into a private `full` marker and simply stop looping rather than re-throwing, since the task only cares that we keep mining until full. `NotAtBelt` (shouldn't happen, we flew there) and `ServerBusy` aren't expected; I leave them alone — they'd fail the run, and the `ensuring` still records credits.
- I disengage before each mine so a battle can't wedge the loop, and I only append to `rows` when the result is actually a `Row` (checked structurally, since the error types aren't `Row`s).

