The previous attempt was two problems: `effect`'s namespace and `Data`/`Exit` aren't usable that way, and more fundamentally a from-scratch retry-on-tag was fragile. The prompt itself tells me the right tools (`Effect.either`, `Effect.catchTags`, `Effect.retry` with `Schedule`), so I'll drive the retry off the *typed* error object (`ServerBusy`) with an exit-based gate.

```ts
import {Effect, Schedule} from 'effect';
import {goTo, note} from 'play';
import type * as E from 'effect/Effect';

const backoff = Schedule.exponential(1_000).pipe(Schedule.mapDuration((d) => d * 2));

// Exponential backoff that retriggers after every failure exit, or skips
// straight to the terminal `else` when the failure is not a ServerBusy.
function retriesOnServerBusy(
  cause: string,
  schedule: Schedule.Schedule<number, unknown, never>,
  else: string,
) {
  return Schedule.recur({
    initial: (exit) =>
      exit._tag === 'Failure' && exit.cause._tag === 'FailException' && exit.defect._tag === cause
        ? schedule.initial(exit.defect)
        : else,
    recurrence: (n, defect) => Schedule.recurrence(n, defect, schedule, false),
  });
}

function onlyOnServerBusy<A, ER, S>(effect: E.Effect<A, never, ER | S>) {
  return (exit: E.Exit<A, ER>) =>
    exit._tag === 'Failure' && exit.cause._tag === 'FailException' && exit.defect._tag === 'ServerBusy'
      ? Effect.void
      : Effect.fail(exit);
}

function retryOnServerBusy<A, E, R>(effect: E.Effect<A, E, R>): E.Effect<A, E, R> {
  return Effect.gen(function* () {
    // Run the first attempt, then let the gate + retry-schedule drive the loop.
    return yield* effect.pipe(
      Effect.either,
      Effect.retryOrDie({
        schedule: retriesOnServerBusy('ServerBusy', backoff, 'stop'),
        onRetry: onlyOnServerBusy,
      }),
    ) as unknown as E.Effect<A, E, R>;
  });
}

export default Effect.gen(function* () {
  const arrived = yield* retryOnServerBusy(goTo('sol_belt'));
  yield* note(`arrived at ${arrived.poi} in ${arrived.system}, used ${arrived.fuel_used} fuel`);
});
