} from 'play';

// Discriminate Left/Right without widening to `unknown` (avoids the
// Effect 3.x `Either<Tag>` awkwardness in the handler environment).
function isLeft(e: unknown): e is {left: any; right?: any} {
  return typeof e === 'object' && e !== null && 'left' in e;
}

export default Effect.gen(function* (): Effect<number, GameError, any> {
  const here = yield* orient();

  // List the missions at this base; if we're not docked there is nothing to list.
  const board = yield* missions().pipe(
    Effect.catchTag('NotDocked', () => Effect.succeed([] as readonly Mission[])),
  );

  let accepted = 0;

  for (const mission of board) {
    if (mission.reward < 100) {
      continue;
    }
    const res = yield* acceptMission(mission.id).pipe(Effect.either);
    if (isLeft(res)) {
      // `res.left` is GameError; treat any non-NoSlots failure as "keep going".
      if (res.left._tag === 'NoSlots') {
        break; // stop accepting once we are full
      }
      continue;
    }
    accepted += 1;
  }

  const done = yield* completeMissions().pipe(Effect.either);
  if (isLeft(done)) {
    if (done.left._tag === 'NothingCompletable') {
      yield* note(`nothing to hand in at ${here.docked_at ?? here.poi}`);
    }
    // any other failure: carry on
  } else {
    yield* note(`turned in ${done.right.completed.length} mission(s)`);
  }

  return accepted;
});
