} from 'play';
import type {Present, Sold} from 'play';

function tagOf(e: unknown): string {
  return e && typeof e === 'object' && '_tag' in e ? String((e as {_tag: unknown})._tag) : 'Unknown';
}

// One mining cycle: mine; if pirates show up, disengage and mine again.
// Noted explicit: mine() -> Effect<Row, InBattle|NotAtBelt|HoldFull, Game>; the recursion
// makes TS infer `any` without a concrete annotation on the constant.
const mineCycle = Effect.gen(function* (): Effect.Promisable<import('play').Row> {
  try {
    return yield* mine();
  } catch (e) {
    if (tagOf(e) === 'InBattle') {
      yield* disengage();
      return yield* mineCycle();
    }
    throw e; // NotAtBelt | HoldFull bubble up
  }
});

// Mine until the hold is full. Other mining failures bubble up to the caller.
const mineUntilFull = Effect.gen(function* () {
  while (true) {
    yield* mineCycle();
    const present = yield* orient();
    if (present.cargo_used >= present.cargo_capacity) return;
  }
});

// Sell everything we hold; the task calls for selling our copper_ore.
// NoBuyer (nothing sold) has nothing better to do than abort.
const sellCopper = Effect.gen(function* (): Effect.Promisable<Sold> {
  return yield* sell([{item_id: 'copper_ore'}]);
});

// One attempt at the whole plan.
const attempt = Effect.gen(function* () {
  yield* goTo('kepler_belt');
  yield* mineUntilFull();
  yield* goTo('kepler_base');
  yield* sellCopper();
  yield* service();
  const c = yield* completeMissions().pipe(
    Effect.catchTag('NothingCompletable', () => Effect.succeed(null)),
  );
  yield* note(`completed ${c === null ? 0 : c.completed.length} mission(s)`);
});

// Whatever happens, the program ends by noting current credits.
export default Effect.gen(function* () {
  yield* attempt.pipe(
    Effect.catchAll((e) => Effect.sync(() => console.error('[abort]', tagOf(e), e))),
  );
  const present = yield* orient().pipe(
    Effect.catchAll((e) =>
      Effect.gen(function* (): Effect.Promisable<Present> {
        // orient shouldn't fail, but a brief busy can interrupt the report; clear it and retry.
        yield* disengage().pipe(
          Effect.catchAll((ee) => Effect.sync(() => console.error('[orient]', tagOf(ee), ee))),
        );
        for (let i = 0; i < 5; i++) {
          const p = yield* orient().pipe(
            Effect.catchAll((ee) => Effect.sync(() => console.error('[orient]', tagOf(ee), ee))),
          );
          if (p.in_battle) yield* disengage();
